333	// groupTitle is the group level's title suffix: the cause it lists.
334	func groupTitle(g fixGroup) string {
335		return g.Subject + " " + g.Change
336	}
337	
338	// groupStatus is the footer's sentence about the selected group, a state of the
339	// screen derived on every frame (Rule 128).
340	func (m Model) groupStatus() sharedcomponents.Status {
341		if g, ok := m.currentGroup(); ok {
342			return sharedcomponents.Status{Text: groupSentence(g)}
343		}
344		return sharedcomponents.Status{}
345	}
346	
347	// groupSentence is what the footer says about the selected group.
348	func groupSentence(g fixGroup) string {
349		count := cveCount(len(g.Members))
350		switch {
351		case g.Key.Unfixed:
352			return "No fix published for " + count
353		case g.Target != "":
354			return count + " closed by one move to " + g.Target
355		}
356		// Several candidate versions, none preferred: no single move is promised.
357		_, options, _ := strings.Cut(g.Change, " -> ")
358		if options == "" || options == "none" {
359			return count + ", no single version to move to"
360		}
361		return count + ", fixed in " + options
362	}
363	
364	// cveCount is "1 CVE" or "N CVEs".
365	func cveCount(n int) string {
366		if n == 1 {
367			return "1 CVE"
368		}
369		return strconv.Itoa(n) + " CVEs"
370	}
