1	package security
2	
3	import (
4		"sort"
5		"strconv"
6		"strings"
7	
8		"charm.land/lipgloss/v2"
9	
10		"github.com/anthnel/devdesk/internal/remediation"
11		"github.com/anthnel/devdesk/internal/scan"
12		"github.com/anthnel/devdesk/internal/ui/datatable"
13		"github.com/anthnel/devdesk/internal/ui/theme"
14	)
15	
16	// DEVDESK-754 (SC1, step 2): the pure half of "Group by fix". Nothing here
17	// touches the Model; the toggle, the level and the rendering live elsewhere.
18	
19	// groupKey identifies a group across two scans: what it is about, never its
20	// members or its target, so a re-scan finds the same row again.
21	type groupKey struct {
22		Ecosystem, Subject, Installed string
23		Unfixed                       bool
24		// Position is remediation.Fix.Position: it keeps two vulnerabilities that
25		// name no package from sharing a key.
26		Position int
27	}
28	
29	// fixGroup is one row of the grouped list.
30	type fixGroup struct {
31		Key      groupKey
32		Severity scan.SeverityLevel
33		// Subject is the package, or the ID of a vulnerability that names none.
34		Subject string
35		// Change is the delta shown in the table, "1.1.1k -> 1.1.1w".
36		Change string
37		// Target is the one version the group moves to, "" when the versions could
38		// not be ordered (several candidates) or none is published.
39		Target string
40		// Status is the Fix column, from fixStatusOf.
41		Status fixStatus
42		// Command is the group's command, "" when none is known or it is not plain
43		// words (scan.PlainWords).
44		Command string
45		// Members are every finding of the group, not only the visible ones.
46		Members []scan.Finding
47	}
48	
49	// cveGroups groups the vulnerabilities of findings by the cause that clears
50	// them, from remediation.GroupAll. Worst severity first, then the most
51	// findings, then Subject, then Change.
52	func cveGroups(findings []scan.Finding) []fixGroup {
53		fixes := remediation.GroupAll(findings)
54		groups := make([]fixGroup, 0, len(fixes))
55		for _, fx := range fixes {
56			if len(fx.Members) == 0 {
57				continue
58			}
59			key := groupKey{Ecosystem: fx.Ecosystem, Subject: fx.Package, Installed: fx.Installed, Unfixed: fx.Unfixed, Position: fx.Position}
60			fx = displaySafe(fx)
61			g := fixGroup{
62				Key:      key,
63				Severity: fx.Severity,
64				Subject:  fx.Package,
65				Change:   fixChange(fx),
66				Target:   fx.Target,
67				Status:   fixStatusOf(fx.Members[0], false),
68				Members:  fx.Members,
69			}
70			if fx.Command != "" && scan.PlainWords(fx.Command) {
71				g.Command = fx.Command
72			}
73			groups = append(groups, g)
74		}
75		sort.SliceStable(groups, func(i, j int) bool {
76			a, b := groups[i], groups[j]
77			if ra, rb := severityRank(a.Severity), severityRank(b.Severity); ra != rb {
78				return ra > rb
79			}
80			if len(a.Members) != len(b.Members) {
81				return len(a.Members) > len(b.Members)
82			}
83			if a.Subject != b.Subject {
84				return a.Subject < b.Subject
85			}
86			return a.Change < b.Change
87		})
88		return groups
89	}
90	
91	// displaySafe is fx with the scan's text made safe for the terminal: the package,
92	// the versions and the candidates are shown as they are in the title, the footer
93	// and the cells, so none may carry an escape sequence, a control or a bidi mark.
94	func displaySafe(fx remediation.Fix) remediation.Fix {
95		fx.Package = inlineText(fx.Package)
96		fx.Installed = inlineText(fx.Installed)
97		fx.Target = inlineText(fx.Target)
98		options := make([]string, len(fx.Options))
99		for i, o := range fx.Options {
100			options[i] = inlineText(o)
101		}
102		fx.Options = options
103		return fx
104	}
105	
106	// fixChange is the delta of a fix: the installed version, an arrow and what it
107	// moves to. An unfixed group moves to none; versions that could not be ordered
108	// are all listed, none preferred.
109	func fixChange(fx remediation.Fix) string {
110		installed := fx.Installed
111		if installed == "" {
112			installed = "unknown"
113		}
114		switch {
115		case fx.Unfixed:
116			return installed + " -> none"
117		case fx.Target != "":
118			return installed + " -> " + fx.Target
119		}
120		var options []string
121		for _, o := range fx.Options {
122			for _, v := range strings.Split(o, ",") {
123				if v = strings.TrimSpace(v); v != "" {
124					options = append(options, v)
125				}
126			}
127		}
128		if len(options) == 0 {
129			return installed + " -> none"
130		}
131		return installed + " -> " + strings.Join(options, " or ")
132	}
133	
134	// findingIdentity is what sameFinding compares, as a map key.
135	type findingIdentity struct {
136		source, rule, file, pkg, version, instance string
137	}
138	
139	func identityOf(f scan.Finding) findingIdentity {
140		return findingIdentity{f.Source, remediation.RuleKey(f.ID), f.File, f.PkgName, f.Version, instanceOf(f)}
141	}
142	
143	// visibleGroups keeps the groups with at least one member in visible (matched
144	// by sameFinding), in the order of all. A kept group keeps all its members.
145	func visibleGroups(all []fixGroup, visible []scan.Finding) []fixGroup {
146		shown := make(map[findingIdentity]struct{}, len(visible))
147		for _, f := range visible {
148			shown[identityOf(f)] = struct{}{}
149		}
150		kept := make([]fixGroup, 0, len(all))
151		for _, g := range all {
152			for _, f := range g.Members {
153				if _, ok := shown[identityOf(f)]; ok {
154					kept = append(kept, g)
155					break
156				}
157			}
158		}
159		return kept
160	}
161	
162	// groupIndexOf is the index of the group that holds f, -1 if none.
163	func groupIndexOf(groups []fixGroup, f scan.Finding) int {
164		for i, g := range groups {
165			for _, member := range g.Members {
166				if sameFinding(member, f) {
167					return i
168				}
169			}
170		}
171		return -1
172	}
173	
174	// groupIndexByKey is the index of the group with key, else prev clamped into
175	// the list, -1 for an empty list.
176	func groupIndexByKey(groups []fixGroup, key groupKey, prev int) int {
177		for i, g := range groups {
178			if g.Key == key {
179				return i
180			}
181		}
182		return clampIndex(prev, len(groups))
183	}
184	
185	// clampIndex puts i into [0, n), -1 when n is 0.
186	func clampIndex(i, n int) int {
187		if n == 0 {
188			return -1
189		}
190		return max(0, min(i, n-1))
191	}
192	
193	// nearestFinding is the index in visible the findings cursor goes to when the
194	// grouped list is left (AC4): the first visible member of g, else prev if it is
195	// still visible, else prevCursor clamped into the list, -1 if visible is empty.
196	func nearestFinding(visible []scan.Finding, g *fixGroup, prev *scan.Finding, prevCursor int) int {
197		if len(visible) == 0 {
198			return -1
199		}
200		if g != nil && len(g.Members) > 0 {
201			members := make(map[findingIdentity]struct{}, len(g.Members))
202			for _, member := range g.Members {
203				members[identityOf(member)] = struct{}{}
204			}
205			for i, f := range visible {
206				if _, ok := members[identityOf(f)]; ok {
207					return i
208				}
209			}
210		}
211		if prev != nil {
212			want := identityOf(*prev)
213			for i, f := range visible {
214				if identityOf(f) == want {
215					return i
216				}
217			}
218		}
219		return clampIndex(prevCursor, len(visible))
220	}
221	
222	// cveGroupColumns describes the grouped list of the CVE tab: Severity, Package,
223	// Change, CVEs, Fix. Cells are plain text (Rule 122); only Severity is coloured,
224	// and it is also its word.
225	func cveGroupColumns() []datatable.Column[fixGroup] {
226		return []datatable.Column[fixGroup]{
227			{
228				Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
229				Cell:  func(g fixGroup) string { return string(g.Severity) },
