374		return datatable.New(datatable.Config[fixGroup]{
375			Columns:    cveGroupColumns(),
376			SortColumn: -1,
377			SelectedStyles: func(g fixGroup) table.Styles {
378				return theme.TableStylesForSeverity(string(g.Severity))
379			},
380		})
381	}
