23	// DEVDESK-754 (SC1, step 3): `g` switches the CVE tab between the findings table
24	// and the grouped list, one row per cause. The findings table is never rebuilt by
25	// the switch: its filter, its sort, its query and its cursor are what the user
26	// left (AC4). Footer timers are never run: the footer is read through Text and
27	// Level. User decisions pinned here: `g` is the third key of the results column;
28	// the mode is held per tab for the life of the view; only the CVE tab groups.
29	
30	// ── Fixtures ─────────────────────────────────────────────────────────────────
31	
32	// groupFindings are the findings of the grouped tests. The CVEs are interleaved
33	// on purpose, so that the first visible member of a group is not the first row of
34	// the table. Groups, worst first: openssl (3 CVEs, CRITICAL), golang.org/x/net
35	// (1, HIGH), zlib (2, MEDIUM, no fix published), libfoo (1, LOW, two candidate
36	// versions).
37	func groupFindings() []scan.Finding {
38		const (
39			crit = scan.SeverityCritical
40			high = scan.SeverityHigh
41			med  = scan.SeverityMedium
42			low  = scan.SeverityLow
43		)
44		net := cve("CVE-4", "golang.org/x/net", "gomod", "0.10.0", "0.23.0", high)
45		net.File = "go.mod"
46		net.FixCommand = "go get golang.org/x/net@v0.23.0"
47		return []scan.Finding{
48			cve("CVE-5", "zlib", "alpine", "1.2", "", med),
49			net,
50			cve("CVE-2", "openssl", "alpine", "1.1.1k", "1.1.1w", high),
51			cve("CVE-6", "zlib", "alpine", "1.2", "", med),
52			cve("CVE-1", "openssl", "alpine", "1.1.1k", "1.1.1w", crit),
53			cve("CVE-7", "libfoo", "npm", "1.0.0", "abc, def", low),
54			cve("CVE-3", "openssl", "alpine", "1.1.1k", "1.1.1w", low),
55			{ID: "aws-access-token", Title: "AWS key committed", Severity: high, Source: scan.SourceGitleaks, File: "config/prod.env", Line: 12, Match: "AKIA..."},
56			{ID: "GPL-3.0", Title: "Copyleft licence", Severity: low, Source: scan.SourceTrivyLicense, File: "go.mod"},
57			{ID: "DS002", Title: "Container runs as root", Severity: high, Source: scan.SourceTrivyMisconfig, File: "Dockerfile"},
58		}
59	}
