781	func TestGroupedViewFitsAtEveryWidth(t *testing.T) {
782		for _, width := range []int{80, 120, 175} {
783			t.Run(fmt.Sprintf("width %d", width), func(t *testing.T) {
784				m := feed(t, groupedModel(t, width), testutil.Key("c"))
785				if got, want := m.groups.RenderedWidth(), width-2; got != want {
786					t.Errorf("RenderedWidth = %d, want %d (Rule 116)", got, want)
787				}
788				body := m.Render()
789				for i, line := range strings.Split(body, "\n") {
790					if w := ansi.StringWidth(line); w > width-2 {
791						t.Errorf("body line %d is %d cells, the viewport holds %d: %q", i, w, width-2, ansi.Strip(line))
792					}
793				}
794				header := firstLine(ansi.Strip(body))
795				for _, title := range []string{"Severity", "Package", "Change", "CVEs", "Fix"} {
796					if !strings.Contains(header, title) {
797						t.Errorf("at %d columns the header %q lost %q", width, header, title)
798					}
799				}
800				footer := strings.Split(m.RenderFooter(width), "\n")
801				if len(footer) != m.GetFooterHeight() {
802					t.Errorf("the footer is %d lines, GetFooterHeight says %d (Rule 124)", len(footer), m.GetFooterHeight())
803				}
804				// The last line is the info line, the one before the blank; the tab
805				// bar sits above them.
806				for i, line := range footer {
807					if i == len(footer)-3 && m.showsResultTabs() {
808						continue
809					}
810					if w := ansi.StringWidth(line); w > width {
811						t.Errorf("footer line %d is %d cells wide, the window holds %d: %q", i, w, width, ansi.Strip(line))
812					}
813				}
814			})
815		}
816	}
