// maxColumnWidth is the widest the detail's text column gets (DEVDESK-751): a
// line longer than this is harder to read than to scroll.
const maxColumnWidth = 110

// scanMount is where a scanned directory is mounted inside a scanner container
// (scan.containerScanPath, unexported there).
const scanMount = "/scan"

// pathToken finds an absolute path in a text: it starts at the beginning of the
// text or after a character that cannot be part of a path name, and stops at
// white space or punctuation that ends a path in a message.
var pathToken = REDACTED

// shortPaths rewrites absolute paths inside text for display: "<target>/" and
// the container mount "/scan/" are removed, a bare target becomes ".", and any
// other path under HOME is folded to "~/". target is used only when it is an
// absolute path (an image reference is ignored). Display only: the finding
// keeps its text.
func shortPaths(text, target string) string {
	if text == "" {
		return ""
	}
	root := ""
	if filepath.IsAbs(target) {
		if root = filepath.ToSlash(filepath.Clean(target)); root == "/" {
			root = ""
		}
	}
	return pathToken.ReplaceAllStringFunc(text, func(match string) string {
		at := strings.IndexByte(match, '/')
		path, tail := match[at:], ""
		// A sentence can end on a path: "cannot read /repo."
		if trimmed := strings.TrimRight(path, "."); trimmed != "" {
			path, tail = trimmed, path[len(trimmed):]
		}
		return match[:at] + shortPath(path, root) + tail
	})
}

// shortPath shortens one absolute path: relative to the target, relative to the
// container mount, or folded under HOME.
func shortPath(path, root string) string {
	for _, base := range []string{root, scanMount} {
		switch {
		case base == "":
		case path == base:
			return "."
		case strings.HasPrefix(path, base+"/"):
			if rest := strings.TrimLeft(path[len(base):], "/"); rest != "" {
				return rest
			}
			return "."
		}
	}
	return theme.FoldHome(path)
}

// oneLine is the first line of text, cut to width cells with theme.Ellipsis.
// It measures with x/ansi, as the viewport does, not with runewidth, after the
// tabs and carriage returns are gone: x/ansi counts a tab as no cell while the
// renderer lays it out as four spaces.
func oneLine(text string, width int) string {
	if width <= 0 {
		return ""
	}
	first, _, _ := strings.Cut(text, "\n")
	first = withoutControlSpace(first)
	if ansi.StringWidth(first) <= width {
		return first
	}
	return ansi.Truncate(first, width, theme.Ellipsis)
}

// cappedLines wraps text at min(width, maxMessageWidth), hard-breaking a token
// longer than that, and keeps the first maxLines lines. hidden counts the wrapped
// lines left out. A blank text gives nil, 0.
func cappedLines(text string, width, maxLines int) (lines []string, hidden int) {
	if strings.TrimSpace(text) == "" {
		return nil, 0
	}
	text = strings.TrimRight(text, " \t\r\n")
	lines = strings.Split(ansi.Wrap(text, max(min(width, maxMessageWidth), 1), ""), "\n")
	if len(lines) > maxLines {
		return lines[:maxLines], len(lines) - maxLines
	}
	return lines, 0
}

// moreLines is the marker after a capped text, "" when nothing was left out.
func moreLines(n int) string {
	switch {
	case n <= 0:
		return ""
	case n == 1:
		return "… 1 more line"
	}
	return fmt.Sprintf("… %d more lines", n)
}

// scrollPosition is "Lines a-b of N" when the content is taller than the
// viewport, "" otherwise.
func scrollPosition(offset, visible, total int) string {
	if visible <= 0 || total <= visible {
		return ""
	}
	offset = max(offset, 0)
	return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
}

// withoutControlSpace makes a scanner's text safe for the terminal: an escape
// sequence (CSI, OSC) is removed whole, a tab becomes four spaces, which is how
// the renderer lays it out, and every other control character (C0, C1, a carriage
// return) is dropped, as are the characters with no visible form that reorder or
// hide text (bidi and zero-width marks, line and paragraph separators). A line
// feed stays: the callers decide what a line is.
func withoutControlSpace(text string) string {
	text = ansi.Strip(text)
	var b strings.Builder
	b.Grow(len(text))
	for _, r := range text {
		switch {
		case r == '\t':
			b.WriteString("    ")
		case r == '\n':
			b.WriteRune(r)
		case unicode.IsControl(r), unicode.In(r, unicode.Zl, unicode.Zp):
		case unicode.Is(unicode.Cf, r) && r != '\u200c' && r != '\u200d':
			// The joiners stay: emoji sequences need them.
		default:
			b.WriteRune(r)
		}
	}
	return b.String()
}

// inlineText is withoutControlSpace for a text that sits on one line (a package
// name, a version): a line feed becomes a space and the ends are trimmed.
func inlineText(text string) string {
	return strings.TrimSpace(strings.ReplaceAll(withoutControlSpace(text), "\n", " "))
}

// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
// return has no width the viewport and the terminal agree on, trailing spaces
// are noise, and a run of blank lines is one blank line. dropBlank removes the
// blank lines altogether (a stderr, where they separate nothing).
func normalizeText(text string, dropBlank bool) string {
	text = withoutControlSpace(text)
	var out []string
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimRight(line, " ")
		blank := line == ""
		switch {
		case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
		default:
			out = append(out, line)
		}
	}
	for len(out) > 0 && out[len(out)-1] == "" {
		out = out[:len(out)-1]
	}
	return strings.Join(out, "\n")
}

// dropBlankLines is normalizeText without any blank line.
func dropBlankLines(text string) string { return normalizeText(text, true) }

// detailsText lays text out for the finding detail: every line it returns is
// styled on the theme background and spans at most width cells, measured with
// x/ansi as the viewport does.
type detailsText struct {
	width int            // cells a line may span
	text  lipgloss.Style // ordinary text
	dim   lipgloss.Style // secondary text
}

func newDetailsText(width int) detailsText {
	return detailsText{
		width: width,
package security

import (
	"fmt"

	"charm.land/bubbles/v2/table"
	tea "charm.land/bubbletea/v2"
	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/forge"
	"github.com/anthnel/devdesk/internal/scan"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
	uiviewer "github.com/anthnel/devdesk/internal/ui/viewer"
)

// findingColumns describes the findings table.
//
// The table opens on the order the scanner reported — `SortColumn: -1`, which
// datatable keeps as a stop on the cycle, so `.` always leads back to it. Every
// column sorts, because `.` was handed back to the sort when the severity floor
// became four tokens (§3.26) and then no column was ever given a `Less`:
// CycleSort returned on its first line and the header advertised a key that did
// nothing at all.
//
// Three columns search, and that is not optional either. Declaring tokens makes
// `Searchable()` true, so `/` already opened a query — against no searchable
// column, which matches nothing and empties the table. The bar's own left half
// says `/ search...` whether or not anything answers it.
//
// Severity searches nothing on purpose: c/h/m/l are the severity filter, and a
// second way to ask one question is what this codebase spends its time
// removing. The Title is not pre-truncated either — bubbles cuts every cell to
// its column width with the same ellipsis, and doing it by hand at width-3
// first only cost three characters of title.
func findingColumns() []datatable.Column[scan.Finding] {
	return []datatable.Column[scan.Finding]{
		{
			Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell: func(f scan.Finding) string { return string(f.Severity) },
			// The same palette the selected row uses, so a severity reads the
			// same colour whether or not the cursor is on it.
			Style: func(f scan.Finding) lipgloss.Style { return theme.SeverityTextStyle(string(f.Severity)) },
			Less:  func(a, b scan.Finding) bool { return severityRank(a.Severity) < severityRank(b.Severity) },
		},
		{
			Title: "ID", Sizing: datatable.SizingContent, MinWidth: 18,
			Cell:   func(f scan.Finding) string { return f.ID },
			Less:   func(a, b scan.Finding) bool { return a.ID < b.ID },
			Search: func(f scan.Finding) string { return f.ID },
		},
		{
			Title: "Title", Sizing: datatable.SizingContent, MinWidth: 20, Flex: 1,
			// The Pod Security label is a prefix of the text (DEVDESK-686); the
			// sort stays on the title and the search sees the label.
			Cell:   titleWithLabel,
			Less:   func(a, b scan.Finding) bool { return a.Title < b.Title },
			Search: func(f scan.Finding) string { return titleWithLabel(f) + " " + f.PkgName + " " + f.File },
		},
		{
			Title: "Source", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 14,
			Cell:   sourceDisplay,
			Less:   func(a, b scan.Finding) bool { return sourceDisplay(a) < sourceDisplay(b) },
			Search: sourceDisplay,
		},
		{
			// Appended last, so the indices above do not move. No Less and no
			// Search: the Title search already matches the file, and a second
			// way to ask the same question is noise. It keeps the end of a long
			// path, which is what tells two findings apart.
			Title: "File", Sizing: datatable.SizingContent, MinWidth: 16, MaxWidth: 40,
			Optional: true, TruncateHead: true,
			Cell: fileCell,
		},
	}
}

// fileColumn is the index of the File column in findingColumns.
const fileColumn = 4

// fileCell is the File cell: plain text (Rule 122), with the scanner container's
// mount removed and a path under HOME folded. The columns are built once, before
// any result exists, so the cell does not know the scanned target (the detail
// does): an absolute path under the target shows as the folded absolute path here
// and as a relative one in the detail. Trivy reports relative paths, so this is
// the rare case.
func fileCell(f scan.Finding) string { return shortPaths(f.File, "") }

// severityRank orders the levels by how bad they are, which is the only order
// worth sorting this column by: alphabetically, CRITICAL lands between no two
// levels it belongs with — HIGH, LOW, MEDIUM — so a descending sort would put
// MEDIUM at the top and bury the finding the user opened the view for.
//
// Ascending is least-severe-first, so `.`'s second press (descending, Rule 111)
// is the one that answers "what is worst here".
//
// UNKNOWN ranks below LOW rather than above CRITICAL: it is what a scanner
// says when it has no score, not a claim that something is worse than critical.
// It has no token either, for the same reason — see severityToken.
func severityRank(s scan.SeverityLevel) int {
	switch s {
	case scan.SeverityCritical:
		return 4
	case scan.SeverityHigh:
		return 3
	case scan.SeverityMedium:
		return 2
	case scan.SeverityLow:
		return 1
	default:
		return 0
	}
}

// findingSelectedStyles colours the selected row by the severity under the
