// empty. A result cached before the dialect was recorded keeps "misconfig".
func sourceDisplay(f scan.Finding) string {
	switch f.Source {
	case scan.SourceTrivyLicense:
		return "license"
	case scan.SourceTrivyMisconfig:
		if f.IaCType != "" {
			return f.IaCType
