			if a := m.canCopyGroupCommand(); a.Enabled() || a.Reason != reasonNoGroupCommand {
				t.Errorf("canCopyGroupCommand = %+v, want %q", a, reasonNoGroupCommand)
			}
			m, cmd := step(t, m, testutil.Key(keymap.Copy))
