func TestMisconfigGroupedViewFitsWithLongNames(t *testing.T) {
	long := strings.Repeat("deeply/nested/", 6) + "Dockerfile"
	findings := []scan.Finding{
		mgFinding("KSV-"+strings.Repeat("9", 60), long, "x", mgCrit),
