type mgKey struct {
	file, rule string
	state      fixState
	reason     string
}

func misconfigGroups(findings []scan.Finding, onDisk bool) []fixGroup {
	index := map[mgKey]int{}
	var groups []fixGroup
	for _, f := range findings {
		if scan.Categorize(f) != scan.CategoryMisconfiguration {
			continue
		}
		st := fixStatusOf(f, onDisk)
		k := mgKey{f.File, remediation.RuleKey(f.ID), st.State, st.Reason}
		i, ok := index[k]
		if !ok {
			i = len(groups)
			index[k] = i
			groups = append(groups, fixGroup{
				Key:      groupKey{File: k.file, Rule: k.rule, Fix: st.State, Subject: ""},
				Severity: f.Severity,
				Subject:  inlineText(shortPaths(f.File, "")),
				Rule:     inlineText(f.ID),
				Status:   st,
			})
		}
		g := &groups[i]
		g.Members = append(g.Members, f)
		if severityRank(f.Severity) > severityRank(g.Severity) {
			g.Severity = f.Severity
		}
	}
	for i := range groups {
		g := &groups[i]
		g.Key.Subject = g.Key.File // not used
		g.Command = commonCommand(g.Members)
	}
	sort.SliceStable(groups, func(i, j int) bool {
		a, b := groups[i], groups[j]
		if ra, rb := severityRank(a.Severity), severityRank(b.Severity); ra != rb {
			return ra > rb
		}
		if len(a.Members) != len(b.Members) {
			return len(a.Members) > len(b.Members)
		}
		if a.Subject != b.Subject {
			return a.Subject < b.Subject
		}
		if a.Key.Rule != b.Key.Rule {
			return a.Key.Rule < b.Key.Rule
		}
		return a.Key.Fix < b.Key.Fix
	})
	return groups
}

func commonCommand(members []scan.Finding) string {
	first, ok := runCommand(members[0])
	if !ok {
		return ""
	}
	for _, f := range members[1:] {
		if c, ok := runCommand(f); !ok || c != first {
			return ""
		}
	}
	return first
}

func misconfigGroupColumns() []datatable.Column[fixGroup] {
	return []datatable.Column[fixGroup]{
		{
			Title: "Severity", Sizing: datatable.SizingFixed, MinWidth: 10,
			Cell:  func(g fixGroup) string { return string(g.Severity) },
			Style: func(g fixGroup) lipgloss.Style { return theme.SeverityTextStyle(string(g.Severity)) },
			Less:  func(a, b fixGroup) bool { return severityRank(a.Severity) < severityRank(b.Severity) },
		},
		{
			Title: "File", Sizing: datatable.SizingContent, MinWidth: 16, MaxWidth: 40, TruncateHead: true,
			Cell: func(g fixGroup) string { return g.Subject },
			Less: func(a, b fixGroup) bool { return a.Subject < b.Subject },
		},
		{
			Title: "Rule", Sizing: datatable.SizingContent, MinWidth: 10, MaxWidth: 24,
			Cell: func(g fixGroup) string { return g.Rule },
			Less: func(a, b fixGroup) bool { return a.Rule < b.Rule },
		},
		{
			Title: "Findings", Sizing: datatable.SizingFixed, MinWidth: 8, DescFirst: true,
			Cell: func(g fixGroup) string { return strconv.Itoa(len(g.Members)) },
			Less: func(a, b fixGroup) bool { return len(a.Members) < len(b.Members) },
		},
		{
			Title: "Fix", Sizing: datatable.SizingContent, MinWidth: 16, MaxWidth: 48, Optional: true,
			Cell: func(g fixGroup) string { return g.Status.Label() },
			Less: func(a, b fixGroup) bool { return a.Status.Label() < b.Status.Label() },
		},
	}
}

func misconfigSentence(g fixGroup) string {
	n := strconv.Itoa(len(g.Members)) + " findings"
	if len(g.Members) == 1 {
		n = "1 finding"
	}
	return n + " · " + g.Status.Label()
}

